/* 表格 AI 数据清洗菜单；演示入口，具体业务执行后续按各功能方案接入。 */
(function () {
  var tipTimer = null;
  var tipCopy = {
    main: ['AI 数据清洗', '用自然语言描述清洗需求，AI 帮你去除重复数据、处理空值并统一数据格式。'],
    menu: ['AI 数据清洗', '选择 AI 数据清洗、AI 函数、AI 分列或 AI 填充，快速整理表格数据。']
  };
  function hideTip() {
    clearTimeout(tipTimer);
    var tip = document.getElementById('et-ai-clean-tip');
    if (tip) tip.hidden = true;
  }
  function queueTip(target) {
    hideTip();
    var menuTrigger = document.querySelector('[data-et-ai-clean-trigger]');
    if (menuTrigger && menuTrigger.getAttribute('aria-expanded') === 'true') return;
    tipTimer = setTimeout(function () {
      if (!target.isConnected) return;
      var tip = document.getElementById('et-ai-clean-tip');
      if (!tip) return;
      var copy = tipCopy[target.getAttribute('data-et-ai-tip')];
      tip.querySelector('.rb-et-clean-tip-title').textContent = copy[0];
      tip.querySelector('.rb-et-clean-tip-description').textContent = copy[1];
      var rect = target.closest('.rb-et-clean-split').getBoundingClientRect();
      tip.hidden = false;
      tip.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - tip.offsetWidth - 8)) + 'px';
      tip.style.top = (rect.bottom + 4) + 'px';
    }, 500);
  }
  document.addEventListener('pointerover', function (e) {
    var target = e.target.closest('[data-et-ai-tip]');
    if (target && !target.contains(e.relatedTarget)) queueTip(target);
  });
  document.addEventListener('pointerout', function (e) {
    var target = e.target.closest('[data-et-ai-tip]');
    if (target && !target.contains(e.relatedTarget)) hideTip();
  });
  document.addEventListener('focusin', function (e) {
    var target = e.target.closest('[data-et-ai-tip]');
    if (target) queueTip(target);
  });
  document.addEventListener('focusout', hideTip);
  function enterCapability(kind) {
    closeMenu(false);
    hideTip();
    if (window.Agent && Agent.prepareEtCapability) Agent.prepareEtCapability(kind);
  }
  function closeMenu(returnFocus) {
    var menu = document.getElementById('et-ai-clean-menu');
    var trigger = document.querySelector('[data-et-ai-clean-trigger]');
    if (menu) menu.hidden = true;
    if (trigger) trigger.closest('.rb-et-clean-split').classList.remove('is-open');
    if (trigger) {
      trigger.setAttribute('aria-expanded', 'false');
      if (returnFocus) trigger.focus();
    }
  }
  function openMenu(trigger, focusItem) {
    var menu = document.getElementById('et-ai-clean-menu');
    if (!menu) return;
    hideTip();
    var rect = trigger.closest('.rb-et-clean-split').getBoundingClientRect();
    menu.hidden = false;
    menu.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - menu.offsetWidth - 8)) + 'px';
    menu.style.top = Math.min(rect.bottom + 4, window.innerHeight - menu.offsetHeight - 8) + 'px';
    trigger.setAttribute('aria-expanded', 'true');
    trigger.closest('.rb-et-clean-split').classList.add('is-open');
    if (focusItem) menu.querySelector('[role="menuitem"]').focus();
  }
  document.addEventListener('click', function (e) {
    hideTip();
    var action = e.target.closest('[data-et-ai-clean-action]');
    if (action) { enterCapability('clean'); return; }
    var capability = e.target.closest('[data-et-ai-capability]');
    if (capability) { enterCapability(capability.getAttribute('data-et-ai-capability')); return; }
    var trigger = e.target.closest('[data-et-ai-clean-trigger]');
    if (trigger) {
      if (trigger.getAttribute('aria-expanded') === 'true') closeMenu(false);
      else openMenu(trigger, false);
      return;
    }
    var item = e.target.closest('.rb-et-ai-menu [role="menuitem"]');
    if (item) { closeMenu(true); return; }
    closeMenu(false);
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') hideTip();
    var trigger = e.target.closest('[data-et-ai-clean-trigger]');
    if (trigger && e.key === 'ArrowDown') { e.preventDefault(); openMenu(trigger, true); return; }
    var menu = e.target.closest('.rb-et-ai-menu');
    if (!menu) return;
    if (e.key === 'Escape') { e.preventDefault(); closeMenu(true); return; }
    if (e.key === 'Tab') { closeMenu(false); return; }
    if (['ArrowDown', 'ArrowUp', 'Home', 'End'].indexOf(e.key) < 0) return;
    e.preventDefault();
    var items = Array.prototype.slice.call(menu.querySelectorAll('[role="menuitem"]'));
    var index = items.indexOf(document.activeElement);
    if (e.key === 'Home') index = 0;
    else if (e.key === 'End') index = items.length - 1;
    else index = (index + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
    items[index].focus();
  });
  window.addEventListener('resize', function () { closeMenu(false); hideTip(); });
  document.addEventListener('scroll', function (e) {
    if (!e.target.closest || !e.target.closest('.rb-et-ai-menu')) { closeMenu(false); hideTip(); }
  }, true);
})();
